const pointInRect=(p,r)=>p.x>=r.x&&p.x<=r.x+r.w&&p.y>=r.y&&p.y<=r.y+r.h;
const orientation=(a,b,c)=>Math.sign((b.y-a.y)*(c.x-b.x)-(b.x-a.x)*(c.y-b.y));
const intersects=(a,b,c,d)=>orientation(a,b,c)!==orientation(a,b,d)&&orientation(c,d,a)!==orientation(c,d,b);
function segmentHitsRect(a,b,r){if(pointInRect(a,r)||pointInRect(b,r))return true;if(a.y===b.y&&a.y>=r.y&&a.y<=r.y+r.h&&Math.max(a.x,b.x)>=r.x&&Math.min(a.x,b.x)<=r.x+r.w)return true;if(a.x===b.x&&a.x>=r.x&&a.x<=r.x+r.w&&Math.max(a.y,b.y)>=r.y&&Math.min(a.y,b.y)<=r.y+r.h)return true;const p1={x:r.x,y:r.y},p2={x:r.x+r.w,y:r.y},p3={x:r.x+r.w,y:r.y+r.h},p4={x:r.x,y:r.y+r.h};return intersects(a,b,p1,p2)||intersects(a,b,p2,p3)||intersects(a,b,p3,p4)||intersects(a,b,p4,p1);}
const length=points=>points.slice(1).reduce((sum,p,i)=>sum+Math.hypot(p.x-points[i].x,p.y-points[i].y),0);
const collisions=(points,rects)=>points.slice(1).reduce((sum,p,i)=>sum+rects.filter(r=>segmentHitsRect(points[i],p,r)).length,0);
export function routePoints(start,end,mode='straight',obstacles=[]){if(mode==='straight'||mode==='curve')return [start,end];const mx=(start.x+end.x)/2,my=(start.y+end.y)/2,candidates=[[start,{x:mx,y:start.y},{x:mx,y:end.y},end],[start,{x:start.x,y:my},{x:end.x,y:my},end]];if(mode==='smart'){const margin=24,rects=obstacles.map(r=>({x:r.x-margin,y:r.y-margin,w:r.w+margin*2,h:r.h+margin*2}));for(const r of rects){candidates.push([start,{x:start.x,y:r.y-1},{x:end.x,y:r.y-1},end],[start,{x:start.x,y:r.y+r.h+1},{x:end.x,y:r.y+r.h+1},end],[start,{x:r.x-1,y:start.y},{x:r.x-1,y:end.y},end],[start,{x:r.x+r.w+1,y:start.y},{x:r.x+r.w+1,y:end.y},end]);}return candidates.sort((a,b)=>(collisions(a,rects)*1e6+length(a)+a.length*4)-(collisions(b,rects)*1e6+length(b)+b.length*4))[0];}return candidates[0];}
export function pathData(points,mode='straight'){if(!points.length)return '';if(mode==='curve'&&points.length===2){const [a,b]=points,dx=(b.x-a.x)*.45;return `M ${a.x} ${a.y} C ${a.x+dx} ${a.y}, ${b.x-dx} ${b.y}, ${b.x} ${b.y}`;}return `M ${points[0].x} ${points[0].y}`+points.slice(1).map(p=>` L ${p.x} ${p.y}`).join('');}
export function pathBounds(points,padding=20){return {x:Math.min(...points.map(p=>p.x))-padding,y:Math.min(...points.map(p=>p.y))-padding,w:Math.max(1,Math.max(...points.map(p=>p.x))-Math.min(...points.map(p=>p.x))+padding*2),h:Math.max(1,Math.max(...points.map(p=>p.y))-Math.min(...points.map(p=>p.y))+padding*2)};}
